window.__code__["tool-base-py"] = {"code_id": "tool-base-py", "kind": "src", "title": "_base.py", "source_path": "agentscope/src/agentscope/tool/_base.py", "highlight_line": null, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># -*- coding: utf-8 -*-</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-com\"># pylint: disable=unused-argument</span></span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;The tool protocol in agentscope.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\"><span class=\"c-kw\">import</span> inspect</span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\"><span class=\"c-kw\">import</span> os</span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\"><span class=\"c-kw\">from</span> abc <span class=\"c-kw\">import</span> abstractmethod, ABC</span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\"><span class=\"c-kw\">from</span> pathlib <span class=\"c-kw\">import</span> Path</span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\"><span class=\"c-kw\">from</span> typing <span class=\"c-kw\">import</span> AsyncGenerator, Any, Callable, List</span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\"><span class=\"c-kw\">from</span> pydantic <span class=\"c-kw\">import</span> BaseModel</span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ._constants <span class=\"c-kw\">import</span> DEFAULT_DANGEROUS_FILES, DEFAULT_DANGEROUS_DIRECTORIES</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ..permission <span class=\"c-kw\">import</span> (</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\">    PermissionContext,</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\">    PermissionDecision,</span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\">    PermissionRule,</span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\">    PermissionBehavior,</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\">)</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ._response <span class=\"c-kw\">import</span> ToolChunk</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ._utils <span class=\"c-kw\">import</span> _remove_title_field</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\"><span class=\"c-kw\">class</span> ParamsBase(BaseModel):</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;A base <span class=\"c-kw\">class</span> <span class=\"c-kw\">for</span> tool parameters that remove the title field <span class=\"c-kw\">from</span> the</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\">    exported JSON schema.</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">    @classmethod</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> model_json_schema(cls, *args: Any, **kwargs: Any) -&gt; dict:</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;An override implementation to remove the title field <span class=\"c-kw\">from</span> the</span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">        exported schema.</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> _remove_title_field(super().model_json_schema(*args, **kwargs))</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\"><span class=\"c-kw\">class</span> ToolMiddlewareBase(ABC):</span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Base <span class=\"c-kw\">class</span> <span class=\"c-kw\">for</span> tool middlewares.</span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">    A tool middleware wraps the execution of a tool <span class=\"c-kw\">in</span> an onion fashion: the</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">    first registered middleware <span class=\"c-kw\">is</span> the outermost layer <span class=\"c-kw\">and</span> runs its pre-logic</span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">    before any inner layer, then its post-logic after all inner layers have</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">    completed. Subclass this <span class=\"c-kw\">and</span> implement :meth:`on_tool_call` — the signature</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">    <span class=\"c-kw\">is</span> already spelled out, so second-party developers only need to fill <span class=\"c-kw\">in</span> the</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">    body without reasoning about the wrapping protocol.</span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">    Streaming <span class=\"c-kw\">and</span> non-streaming tools are unified: ``next_handler`` always</span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\">    returns an <span class=\"c-kw\">async</span> generator, so a middleware never needs to know whether the</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">    underlying tool yields a stream of chunks <span class=\"c-kw\">or</span> returns a single chunk.</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">    Example:</span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">        ```python</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">        <span class=\"c-kw\">class</span> LoggingMiddleware(ToolMiddlewareBase):</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\">            <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> on_tool_call(<span class=\"c-kw\">self</span>, tool, input_kwargs, next_handler):</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">                print(f<span class=\"c-str\">&quot;Calling {tool.name} with {input_kwargs}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\">                <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> chunk <span class=\"c-kw\">in</span> next_handler(**input_kwargs):</span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">                    <span class=\"c-kw\">yield</span> chunk</span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">                print(f<span class=\"c-str\">&quot;Finished {tool.name}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\">        tool = MyTool(middlewares=[LoggingMiddleware()])</span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\">        ```</span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"62\"><span class=\"c-no\">62</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"63\"><span class=\"c-no\">63</span><span class=\"c-src\">    @abstractmethod</span></div>\n<div class=\"c-line\" data-line=\"64\"><span class=\"c-no\">64</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> on_tool_call(</span></div>\n<div class=\"c-line\" data-line=\"65\"><span class=\"c-no\">65</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"66\"><span class=\"c-no\">66</span><span class=\"c-src\">        tool: <span class=\"c-str\">&quot;ToolBase&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"67\"><span class=\"c-no\">67</span><span class=\"c-src\">        input_kwargs: dict[str, Any],</span></div>\n<div class=\"c-line\" data-line=\"68\"><span class=\"c-no\">68</span><span class=\"c-src\">        next_handler: Callable[..., AsyncGenerator[ToolChunk, <span class=\"c-kw\">None</span>]],</span></div>\n<div class=\"c-line\" data-line=\"69\"><span class=\"c-no\">69</span><span class=\"c-src\">    ) -&gt; AsyncGenerator[ToolChunk, <span class=\"c-kw\">None</span>]:</span></div>\n<div class=\"c-line\" data-line=\"70\"><span class=\"c-no\">70</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Intercept a single tool invocation.</span></div>\n<div class=\"c-line\" data-line=\"71\"><span class=\"c-no\">71</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"72\"><span class=\"c-no\">72</span><span class=\"c-src\">        Add pre-/post-logic around ``next_handler``, rewrite the tool inputs by</span></div>\n<div class=\"c-line\" data-line=\"73\"><span class=\"c-no\">73</span><span class=\"c-src\">        passing modified keyword arguments to ``next_handler``, <span class=\"c-kw\">or</span> transform</span></div>\n<div class=\"c-line\" data-line=\"74\"><span class=\"c-no\">74</span><span class=\"c-src\">        the yielded chunks.</span></div>\n<div class=\"c-line\" data-line=\"75\"><span class=\"c-no\">75</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"76\"><span class=\"c-no\">76</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"77\"><span class=\"c-no\">77</span><span class=\"c-src\">            tool (`ToolBase`):</span></div>\n<div class=\"c-line\" data-line=\"78\"><span class=\"c-no\">78</span><span class=\"c-src\">                The tool instance being invoked.</span></div>\n<div class=\"c-line\" data-line=\"79\"><span class=\"c-no\">79</span><span class=\"c-src\">            input_kwargs (`dict[str, Any]`):</span></div>\n<div class=\"c-line\" data-line=\"80\"><span class=\"c-no\">80</span><span class=\"c-src\">                The tool&<span class=\"c-com\">#x27;s input arguments for this invocation. Pass them on</span></span></div>\n<div class=\"c-line\" data-line=\"81\"><span class=\"c-no\">81</span><span class=\"c-src\">                via ``next_handler(**input_kwargs)``; mutate <span class=\"c-kw\">or</span> replace them to</span></div>\n<div class=\"c-line\" data-line=\"82\"><span class=\"c-no\">82</span><span class=\"c-src\">                change what the inner layers <span class=\"c-kw\">and</span> the tool itself receive.</span></div>\n<div class=\"c-line\" data-line=\"83\"><span class=\"c-no\">83</span><span class=\"c-src\">            next_handler (`Callable[..., AsyncGenerator[ToolChunk, <span class=\"c-kw\">None</span>]]`):</span></div>\n<div class=\"c-line\" data-line=\"84\"><span class=\"c-no\">84</span><span class=\"c-src\">                Call it <span class=\"c-kw\">as</span> ``next_handler(**input_kwargs)`` to run the next</span></div>\n<div class=\"c-line\" data-line=\"85\"><span class=\"c-no\">85</span><span class=\"c-src\">                layer. It always returns an <span class=\"c-kw\">async</span> generator, regardless of</span></div>\n<div class=\"c-line\" data-line=\"86\"><span class=\"c-no\">86</span><span class=\"c-src\">                whether the underlying tool <span class=\"c-kw\">is</span> streaming <span class=\"c-kw\">or</span> <span class=\"c-kw\">not</span>.</span></div>\n<div class=\"c-line\" data-line=\"87\"><span class=\"c-no\">87</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"88\"><span class=\"c-no\">88</span><span class=\"c-src\">        Yields:</span></div>\n<div class=\"c-line\" data-line=\"89\"><span class=\"c-no\">89</span><span class=\"c-src\">            `ToolChunk`:</span></div>\n<div class=\"c-line\" data-line=\"90\"><span class=\"c-no\">90</span><span class=\"c-src\">                The chunks produced by this tool invocation.</span></div>\n<div class=\"c-line\" data-line=\"91\"><span class=\"c-no\">91</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"92\"><span class=\"c-no\">92</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"93\"><span class=\"c-no\">93</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"94\"><span class=\"c-no\">94</span><span class=\"c-src\"><span class=\"c-kw\">class</span> ToolBase(ABC):</span></div>\n<div class=\"c-line\" data-line=\"95\"><span class=\"c-no\">95</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;The tool protocol.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"96\"><span class=\"c-no\">96</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"97\"><span class=\"c-no\">97</span><span class=\"c-src\">    name: str</span></div>\n<div class=\"c-line\" data-line=\"98\"><span class=\"c-no\">98</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;The name presented to the agent.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"99\"><span class=\"c-no\">99</span><span class=\"c-src\">    description: str</span></div>\n<div class=\"c-line\" data-line=\"100\"><span class=\"c-no\">100</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;The agent-oriented tool description.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"101\"><span class=\"c-no\">101</span><span class=\"c-src\">    input_schema: dict[str, Any]</span></div>\n<div class=\"c-line\" data-line=\"102\"><span class=\"c-no\">102</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;The input schema of the tool, following JSON schema format.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"103\"><span class=\"c-no\">103</span><span class=\"c-src\">    is_concurrency_safe: bool</span></div>\n<div class=\"c-line\" data-line=\"104\"><span class=\"c-no\">104</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;If this tool is concurrency safe.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"105\"><span class=\"c-no\">105</span><span class=\"c-src\">    is_read_only: bool</span></div>\n<div class=\"c-line\" data-line=\"106\"><span class=\"c-no\">106</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;If this tool <span class=\"c-kw\">is</span> read-only, which will be used <span class=\"c-kw\">in</span> the permission</span></div>\n<div class=\"c-line\" data-line=\"107\"><span class=\"c-no\">107</span><span class=\"c-src\">    checking.<span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"108\"><span class=\"c-no\">108</span><span class=\"c-src\">    is_external_tool: bool = <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"109\"><span class=\"c-no\">109</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;If this tool <span class=\"c-kw\">is</span> an external tool, which doesn&<span class=\"c-com\">#x27;t need to implement the</span></span></div>\n<div class=\"c-line\" data-line=\"110\"><span class=\"c-no\">110</span><span class=\"c-src\">    __call__ method <span class=\"c-kw\">and</span> the agent will <span class=\"c-kw\">yield</span> the external tool call event.<span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"111\"><span class=\"c-no\">111</span><span class=\"c-src\">    is_state_injected: bool = <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"112\"><span class=\"c-no\">112</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;If this tool requires agent state to be injected when called. If `<span class=\"c-kw\">True</span>`,</span></div>\n<div class=\"c-line\" data-line=\"113\"><span class=\"c-no\">113</span><span class=\"c-src\">    the state will be injected by an argument named `_agent_state`. Note your</span></div>\n<div class=\"c-line\" data-line=\"114\"><span class=\"c-no\">114</span><span class=\"c-src\">    tool should be able to accept such argument.</span></div>\n<div class=\"c-line\" data-line=\"115\"><span class=\"c-no\">115</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"116\"><span class=\"c-no\">116</span><span class=\"c-src\">    is_mcp: bool = <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"117\"><span class=\"c-no\">117</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;If this tool is an MCP tool, which will be used in the permission&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"118\"><span class=\"c-no\">118</span><span class=\"c-src\">    mcp_name: str | <span class=\"c-kw\">None</span> = <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"119\"><span class=\"c-no\">119</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;The name of the MCP server this tool belongs to, which <span class=\"c-kw\">is</span> required <span class=\"c-kw\">if</span></span></div>\n<div class=\"c-line\" data-line=\"120\"><span class=\"c-no\">120</span><span class=\"c-src\">    this tool <span class=\"c-kw\">is</span> an MCP tool.<span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"121\"><span class=\"c-no\">121</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"122\"><span class=\"c-no\">122</span><span class=\"c-src\">    <span class=\"c-com\"># Class attributes for dangerous path checking</span></span></div>\n<div class=\"c-line\" data-line=\"123\"><span class=\"c-no\">123</span><span class=\"c-src\">    dangerous_files: list[str] = DEFAULT_DANGEROUS_FILES</span></div>\n<div class=\"c-line\" data-line=\"124\"><span class=\"c-no\">124</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;List of dangerous files that should be protected from auto-editing.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"125\"><span class=\"c-no\">125</span><span class=\"c-src\">    dangerous_directories: list[str] = DEFAULT_DANGEROUS_DIRECTORIES</span></div>\n<div class=\"c-line\" data-line=\"126\"><span class=\"c-no\">126</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;List of dangerous directories that should be protected <span class=\"c-kw\">from</span></span></div>\n<div class=\"c-line\" data-line=\"127\"><span class=\"c-no\">127</span><span class=\"c-src\">    auto-editing.<span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"128\"><span class=\"c-no\">128</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"129\"><span class=\"c-no\">129</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> __init__(</span></div>\n<div class=\"c-line\" data-line=\"130\"><span class=\"c-no\">130</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"131\"><span class=\"c-no\">131</span><span class=\"c-src\">        middlewares: List[<span class=\"c-str\">&quot;ToolMiddlewareBase&quot;</span>] | <span class=\"c-kw\">None</span> = <span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"132\"><span class=\"c-no\">132</span><span class=\"c-src\">    ) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"133\"><span class=\"c-no\">133</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Initialize the tool <span class=\"c-kw\">with</span> optional middlewares.</span></div>\n<div class=\"c-line\" data-line=\"134\"><span class=\"c-no\">134</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"135\"><span class=\"c-no\">135</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"136\"><span class=\"c-no\">136</span><span class=\"c-src\">            middlewares (`List[ToolMiddlewareBase] | <span class=\"c-kw\">None</span>`, optional):</span></div>\n<div class=\"c-line\" data-line=\"137\"><span class=\"c-no\">137</span><span class=\"c-src\">                A list of :<span class=\"c-kw\">class</span>:`ToolMiddlewareBase` instances wrapping the</span></div>\n<div class=\"c-line\" data-line=\"138\"><span class=\"c-no\">138</span><span class=\"c-src\">                tool execution <span class=\"c-kw\">in</span> an onion fashion. Defaults to an empty list.</span></div>\n<div class=\"c-line\" data-line=\"139\"><span class=\"c-no\">139</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"140\"><span class=\"c-no\">140</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>._middlewares: List[<span class=\"c-str\">&quot;ToolMiddlewareBase&quot;</span>] = (</span></div>\n<div class=\"c-line\" data-line=\"141\"><span class=\"c-no\">141</span><span class=\"c-src\">            middlewares <span class=\"c-kw\">if</span> middlewares <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">None</span> <span class=\"c-kw\">else</span> []</span></div>\n<div class=\"c-line\" data-line=\"142\"><span class=\"c-no\">142</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"143\"><span class=\"c-no\">143</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"144\"><span class=\"c-no\">144</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> call(</span></div>\n<div class=\"c-line\" data-line=\"145\"><span class=\"c-no\">145</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"146\"><span class=\"c-no\">146</span><span class=\"c-src\">        *args: Any,</span></div>\n<div class=\"c-line\" data-line=\"147\"><span class=\"c-no\">147</span><span class=\"c-src\">        **kwargs: Any,</span></div>\n<div class=\"c-line\" data-line=\"148\"><span class=\"c-no\">148</span><span class=\"c-src\">    ) -&gt; ToolChunk | AsyncGenerator[ToolChunk, <span class=\"c-kw\">None</span>]:</span></div>\n<div class=\"c-line\" data-line=\"149\"><span class=\"c-no\">149</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Execute the tool logic.</span></div>\n<div class=\"c-line\" data-line=\"150\"><span class=\"c-no\">150</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"151\"><span class=\"c-no\">151</span><span class=\"c-src\">        This <span class=\"c-kw\">is</span> the new override point <span class=\"c-kw\">for</span> tool implementations.</span></div>\n<div class=\"c-line\" data-line=\"152\"><span class=\"c-no\">152</span><span class=\"c-src\">        Subclasses should override this method instead of</span></div>\n<div class=\"c-line\" data-line=\"153\"><span class=\"c-no\">153</span><span class=\"c-src\">        :meth:`__call__`.  The base implementation raises</span></div>\n<div class=\"c-line\" data-line=\"154\"><span class=\"c-no\">154</span><span class=\"c-src\">        :exc:`NotImplementedError` <span class=\"c-kw\">for</span> non-external tools <span class=\"c-kw\">and</span></span></div>\n<div class=\"c-line\" data-line=\"155\"><span class=\"c-no\">155</span><span class=\"c-src\">        :exc:`RuntimeError` <span class=\"c-kw\">for</span> external tools.</span></div>\n<div class=\"c-line\" data-line=\"156\"><span class=\"c-no\">156</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"157\"><span class=\"c-no\">157</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"158\"><span class=\"c-no\">158</span><span class=\"c-src\">            **kwargs: Tool input arguments.</span></div>\n<div class=\"c-line\" data-line=\"159\"><span class=\"c-no\">159</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"160\"><span class=\"c-no\">160</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"161\"><span class=\"c-no\">161</span><span class=\"c-src\">            `ToolChunk | AsyncGenerator[ToolChunk, <span class=\"c-kw\">None</span>]`:</span></div>\n<div class=\"c-line\" data-line=\"162\"><span class=\"c-no\">162</span><span class=\"c-src\">                A single :<span class=\"c-kw\">class</span>:`~agentscope.tool.ToolChunk` <span class=\"c-kw\">or</span> an</span></div>\n<div class=\"c-line\" data-line=\"163\"><span class=\"c-no\">163</span><span class=\"c-src\">                <span class=\"c-kw\">async</span> generator that yields them.</span></div>\n<div class=\"c-line\" data-line=\"164\"><span class=\"c-no\">164</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"165\"><span class=\"c-no\">165</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">self</span>.is_external_tool:</span></div>\n<div class=\"c-line\" data-line=\"166\"><span class=\"c-no\">166</span><span class=\"c-src\">            <span class=\"c-kw\">raise</span> NotImplementedError(</span></div>\n<div class=\"c-line\" data-line=\"167\"><span class=\"c-no\">167</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;{self.__class__.__name__} does not implement call&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"168\"><span class=\"c-no\">168</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"169\"><span class=\"c-no\">169</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"170\"><span class=\"c-no\">170</span><span class=\"c-src\">        <span class=\"c-kw\">raise</span> RuntimeError(</span></div>\n<div class=\"c-line\" data-line=\"171\"><span class=\"c-no\">171</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;{self.__class__.__name__} is an external tool and should not &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"172\"><span class=\"c-no\">172</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;be called directly&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"173\"><span class=\"c-no\">173</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"174\"><span class=\"c-no\">174</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"175\"><span class=\"c-no\">175</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> __call__(</span></div>\n<div class=\"c-line\" data-line=\"176\"><span class=\"c-no\">176</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"177\"><span class=\"c-no\">177</span><span class=\"c-src\">        *args: Any,</span></div>\n<div class=\"c-line\" data-line=\"178\"><span class=\"c-no\">178</span><span class=\"c-src\">        **kwargs: Any,</span></div>\n<div class=\"c-line\" data-line=\"179\"><span class=\"c-no\">179</span><span class=\"c-src\">    ) -&gt; ToolChunk | AsyncGenerator[ToolChunk, <span class=\"c-kw\">None</span>]:</span></div>\n<div class=\"c-line\" data-line=\"180\"><span class=\"c-no\">180</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Invoke the tool, layering any registered middlewares around</span></div>\n<div class=\"c-line\" data-line=\"181\"><span class=\"c-no\">181</span><span class=\"c-src\">        :meth:`call`.</span></div>\n<div class=\"c-line\" data-line=\"182\"><span class=\"c-no\">182</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"183\"><span class=\"c-no\">183</span><span class=\"c-src\">        Tools are always invoked <span class=\"c-kw\">with</span> keyword arguments only. ``*args`` <span class=\"c-kw\">is</span></span></div>\n<div class=\"c-line\" data-line=\"184\"><span class=\"c-no\">184</span><span class=\"c-src\">        accepted <span class=\"c-kw\">in</span> the signature solely to stay Liskov-compatible <span class=\"c-kw\">with</span></span></div>\n<div class=\"c-line\" data-line=\"185\"><span class=\"c-no\">185</span><span class=\"c-src\">        subclasses that override ``__call__`` <span class=\"c-kw\">with</span> their own positional</span></div>\n<div class=\"c-line\" data-line=\"186\"><span class=\"c-no\">186</span><span class=\"c-src\">        parameters; any positional argument actually passed here <span class=\"c-kw\">is</span> rejected</span></div>\n<div class=\"c-line\" data-line=\"187\"><span class=\"c-no\">187</span><span class=\"c-src\">        (raising :exc:`TypeError`) so it fails loudly instead of being silently</span></div>\n<div class=\"c-line\" data-line=\"188\"><span class=\"c-no\">188</span><span class=\"c-src\">        dropped.</span></div>\n<div class=\"c-line\" data-line=\"189\"><span class=\"c-no\">189</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"190\"><span class=\"c-no\">190</span><span class=\"c-src\">        Middlewares are applied <span class=\"c-kw\">in</span> an onion fashion: the first registered</span></div>\n<div class=\"c-line\" data-line=\"191\"><span class=\"c-no\">191</span><span class=\"c-src\">        middleware <span class=\"c-kw\">is</span> the outermost layer <span class=\"c-kw\">and</span> runs its pre-logic before</span></div>\n<div class=\"c-line\" data-line=\"192\"><span class=\"c-no\">192</span><span class=\"c-src\">        any inner layers, then its post-logic after all inner layers</span></div>\n<div class=\"c-line\" data-line=\"193\"><span class=\"c-no\">193</span><span class=\"c-src\">        have completed.</span></div>\n<div class=\"c-line\" data-line=\"194\"><span class=\"c-no\">194</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"195\"><span class=\"c-no\">195</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> args:</span></div>\n<div class=\"c-line\" data-line=\"196\"><span class=\"c-no\">196</span><span class=\"c-src\">            <span class=\"c-kw\">raise</span> TypeError(</span></div>\n<div class=\"c-line\" data-line=\"197\"><span class=\"c-no\">197</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;{type(self).__name__} must be called with keyword arguments &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"198\"><span class=\"c-no\">198</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;only, but got {len(args)} positional argument(s).&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"199\"><span class=\"c-no\">199</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"200\"><span class=\"c-no\">200</span><span class=\"c-src\">        <span class=\"c-com\"># ``getattr`` with a default so the no-middleware path keeps working</span></span></div>\n<div class=\"c-line\" data-line=\"201\"><span class=\"c-no\">201</span><span class=\"c-src\">        <span class=\"c-com\"># even if a subclass overrides ``__init__`` without calling</span></span></div>\n<div class=\"c-line\" data-line=\"202\"><span class=\"c-no\">202</span><span class=\"c-src\">        <span class=\"c-com\"># ``super().__init__()``.</span></span></div>\n<div class=\"c-line\" data-line=\"203\"><span class=\"c-no\">203</span><span class=\"c-src\">        middlewares = getattr(<span class=\"c-kw\">self</span>, <span class=\"c-str\">&quot;_middlewares&quot;</span>, [])</span></div>\n<div class=\"c-line\" data-line=\"204\"><span class=\"c-no\">204</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> middlewares:</span></div>\n<div class=\"c-line\" data-line=\"205\"><span class=\"c-no\">205</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> inspect.isasyncgenfunction(<span class=\"c-kw\">self</span>.call):</span></div>\n<div class=\"c-line\" data-line=\"206\"><span class=\"c-no\">206</span><span class=\"c-src\">                <span class=\"c-kw\">return</span> <span class=\"c-kw\">self</span>.call(**kwargs)</span></div>\n<div class=\"c-line\" data-line=\"207\"><span class=\"c-no\">207</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>.call(**kwargs)</span></div>\n<div class=\"c-line\" data-line=\"208\"><span class=\"c-no\">208</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"209\"><span class=\"c-no\">209</span><span class=\"c-src\">        <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> execute_chain(</span></div>\n<div class=\"c-line\" data-line=\"210\"><span class=\"c-no\">210</span><span class=\"c-src\">            index: int = 0,</span></div>\n<div class=\"c-line\" data-line=\"211\"><span class=\"c-no\">211</span><span class=\"c-src\">            **chain_kwargs: Any,</span></div>\n<div class=\"c-line\" data-line=\"212\"><span class=\"c-no\">212</span><span class=\"c-src\">        ) -&gt; AsyncGenerator[ToolChunk, <span class=\"c-kw\">None</span>]:</span></div>\n<div class=\"c-line\" data-line=\"213\"><span class=\"c-no\">213</span><span class=\"c-src\">            <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Execute the tool middleware chain.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"214\"><span class=\"c-no\">214</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> index &gt;= len(middlewares):</span></div>\n<div class=\"c-line\" data-line=\"215\"><span class=\"c-no\">215</span><span class=\"c-src\">                <span class=\"c-com\"># Innermost layer: run the tool&#x27;s own ``call``. ``call`` is</span></span></div>\n<div class=\"c-line\" data-line=\"216\"><span class=\"c-no\">216</span><span class=\"c-src\">                <span class=\"c-com\"># always async but comes in two shapes — an async generator</span></span></div>\n<div class=\"c-line\" data-line=\"217\"><span class=\"c-no\">217</span><span class=\"c-src\">                <span class=\"c-com\"># function (e.g. ``Bash``) or a coroutine returning a single</span></span></div>\n<div class=\"c-line\" data-line=\"218\"><span class=\"c-no\">218</span><span class=\"c-src\">                <span class=\"c-com\"># ``ToolChunk`` / an async generator (e.g. ``FunctionTool``).</span></span></div>\n<div class=\"c-line\" data-line=\"219\"><span class=\"c-no\">219</span><span class=\"c-src\">                <span class=\"c-com\"># Normalize both into a single stream so middlewares never have</span></span></div>\n<div class=\"c-line\" data-line=\"220\"><span class=\"c-no\">220</span><span class=\"c-src\">                <span class=\"c-com\"># to distinguish them.</span></span></div>\n<div class=\"c-line\" data-line=\"221\"><span class=\"c-no\">221</span><span class=\"c-src\">                <span class=\"c-kw\">if</span> inspect.isasyncgenfunction(<span class=\"c-kw\">self</span>.call):</span></div>\n<div class=\"c-line\" data-line=\"222\"><span class=\"c-no\">222</span><span class=\"c-src\">                    <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> chunk <span class=\"c-kw\">in</span> <span class=\"c-kw\">self</span>.call(**chain_kwargs):</span></div>\n<div class=\"c-line\" data-line=\"223\"><span class=\"c-no\">223</span><span class=\"c-src\">                        <span class=\"c-kw\">yield</span> chunk</span></div>\n<div class=\"c-line\" data-line=\"224\"><span class=\"c-no\">224</span><span class=\"c-src\">                <span class=\"c-kw\">else</span>:</span></div>\n<div class=\"c-line\" data-line=\"225\"><span class=\"c-no\">225</span><span class=\"c-src\">                    result = <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>.call(**chain_kwargs)</span></div>\n<div class=\"c-line\" data-line=\"226\"><span class=\"c-no\">226</span><span class=\"c-src\">                    <span class=\"c-kw\">if</span> isinstance(result, AsyncGenerator):</span></div>\n<div class=\"c-line\" data-line=\"227\"><span class=\"c-no\">227</span><span class=\"c-src\">                        <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> chunk <span class=\"c-kw\">in</span> result:</span></div>\n<div class=\"c-line\" data-line=\"228\"><span class=\"c-no\">228</span><span class=\"c-src\">                            <span class=\"c-kw\">yield</span> chunk</span></div>\n<div class=\"c-line\" data-line=\"229\"><span class=\"c-no\">229</span><span class=\"c-src\">                    <span class=\"c-kw\">else</span>:</span></div>\n<div class=\"c-line\" data-line=\"230\"><span class=\"c-no\">230</span><span class=\"c-src\">                        <span class=\"c-kw\">yield</span> result</span></div>\n<div class=\"c-line\" data-line=\"231\"><span class=\"c-no\">231</span><span class=\"c-src\">            <span class=\"c-kw\">else</span>:</span></div>\n<div class=\"c-line\" data-line=\"232\"><span class=\"c-no\">232</span><span class=\"c-src\">                mw = middlewares[index]</span></div>\n<div class=\"c-line\" data-line=\"233\"><span class=\"c-no\">233</span><span class=\"c-src\">                input_kwargs = dict(chain_kwargs)</span></div>\n<div class=\"c-line\" data-line=\"234\"><span class=\"c-no\">234</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"235\"><span class=\"c-no\">235</span><span class=\"c-src\">                <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> next_handler(</span></div>\n<div class=\"c-line\" data-line=\"236\"><span class=\"c-no\">236</span><span class=\"c-src\">                    **kw: Any,</span></div>\n<div class=\"c-line\" data-line=\"237\"><span class=\"c-no\">237</span><span class=\"c-src\">                ) -&gt; AsyncGenerator[ToolChunk, <span class=\"c-kw\">None</span>]:</span></div>\n<div class=\"c-line\" data-line=\"238\"><span class=\"c-no\">238</span><span class=\"c-src\">                    <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> chunk <span class=\"c-kw\">in</span> execute_chain(index + 1, **kw):</span></div>\n<div class=\"c-line\" data-line=\"239\"><span class=\"c-no\">239</span><span class=\"c-src\">                        <span class=\"c-kw\">yield</span> chunk</span></div>\n<div class=\"c-line\" data-line=\"240\"><span class=\"c-no\">240</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"241\"><span class=\"c-no\">241</span><span class=\"c-src\">                <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> chunk <span class=\"c-kw\">in</span> mw.on_tool_call(</span></div>\n<div class=\"c-line\" data-line=\"242\"><span class=\"c-no\">242</span><span class=\"c-src\">                    tool=<span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"243\"><span class=\"c-no\">243</span><span class=\"c-src\">                    input_kwargs=input_kwargs,</span></div>\n<div class=\"c-line\" data-line=\"244\"><span class=\"c-no\">244</span><span class=\"c-src\">                    next_handler=next_handler,</span></div>\n<div class=\"c-line\" data-line=\"245\"><span class=\"c-no\">245</span><span class=\"c-src\">                ):</span></div>\n<div class=\"c-line\" data-line=\"246\"><span class=\"c-no\">246</span><span class=\"c-src\">                    <span class=\"c-kw\">yield</span> chunk</span></div>\n<div class=\"c-line\" data-line=\"247\"><span class=\"c-no\">247</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"248\"><span class=\"c-no\">248</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> execute_chain(**kwargs)</span></div>\n<div class=\"c-line\" data-line=\"249\"><span class=\"c-no\">249</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"250\"><span class=\"c-no\">250</span><span class=\"c-src\">    @abstractmethod</span></div>\n<div class=\"c-line\" data-line=\"251\"><span class=\"c-no\">251</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> check_permissions(</span></div>\n<div class=\"c-line\" data-line=\"252\"><span class=\"c-no\">252</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"253\"><span class=\"c-no\">253</span><span class=\"c-src\">        tool_input: dict[str, Any],</span></div>\n<div class=\"c-line\" data-line=\"254\"><span class=\"c-no\">254</span><span class=\"c-src\">        context: PermissionContext,</span></div>\n<div class=\"c-line\" data-line=\"255\"><span class=\"c-no\">255</span><span class=\"c-src\">    ) -&gt; PermissionDecision:</span></div>\n<div class=\"c-line\" data-line=\"256\"><span class=\"c-no\">256</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Check permissions for the tool usage.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"257\"><span class=\"c-no\">257</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"258\"><span class=\"c-no\">258</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> check_read_only(</span></div>\n<div class=\"c-line\" data-line=\"259\"><span class=\"c-no\">259</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"260\"><span class=\"c-no\">260</span><span class=\"c-src\">        tool_input: dict[str, Any],</span></div>\n<div class=\"c-line\" data-line=\"261\"><span class=\"c-no\">261</span><span class=\"c-src\">    ) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"262\"><span class=\"c-no\">262</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Decide whether this specific invocation <span class=\"c-kw\">is</span> read-only.</span></div>\n<div class=\"c-line\" data-line=\"263\"><span class=\"c-no\">263</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"264\"><span class=\"c-no\">264</span><span class=\"c-src\">        Returns the static :attr:`is_read_only` attribute by default.</span></div>\n<div class=\"c-line\" data-line=\"265\"><span class=\"c-no\">265</span><span class=\"c-src\">        Subclasses <span class=\"c-kw\">with</span> input-dependent semantics (e.g. ``Bash``) should</span></div>\n<div class=\"c-line\" data-line=\"266\"><span class=\"c-no\">266</span><span class=\"c-src\">        override this to inspect ``tool_input`` — <span class=\"c-kw\">for</span> example, ``Bash`` <span class=\"c-kw\">is</span></span></div>\n<div class=\"c-line\" data-line=\"267\"><span class=\"c-no\">267</span><span class=\"c-src\">        statically marked <span class=\"c-kw\">as</span> <span class=\"c-kw\">not</span> read-only but ``ls -a`` <span class=\"c-kw\">is</span> <span class=\"c-kw\">in</span> fact read-only.</span></div>\n<div class=\"c-line\" data-line=\"268\"><span class=\"c-no\">268</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"269\"><span class=\"c-no\">269</span><span class=\"c-src\">        Should be cheap — the permission engine may call this before the</span></div>\n<div class=\"c-line\" data-line=\"270\"><span class=\"c-no\">270</span><span class=\"c-src\">        full :meth:`check_permissions` flow.</span></div>\n<div class=\"c-line\" data-line=\"271\"><span class=\"c-no\">271</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"272\"><span class=\"c-no\">272</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"273\"><span class=\"c-no\">273</span><span class=\"c-src\">            tool_input (`dict[str, Any]`):</span></div>\n<div class=\"c-line\" data-line=\"274\"><span class=\"c-no\">274</span><span class=\"c-src\">                The tool input data <span class=\"c-kw\">for</span> this invocation.</span></div>\n<div class=\"c-line\" data-line=\"275\"><span class=\"c-no\">275</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"276\"><span class=\"c-no\">276</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"277\"><span class=\"c-no\">277</span><span class=\"c-src\">            `bool`:</span></div>\n<div class=\"c-line\" data-line=\"278\"><span class=\"c-no\">278</span><span class=\"c-src\">                ``<span class=\"c-kw\">True</span>`` <span class=\"c-kw\">if</span> this invocation <span class=\"c-kw\">is</span> read-only, ``<span class=\"c-kw\">False</span>`` otherwise.</span></div>\n<div class=\"c-line\" data-line=\"279\"><span class=\"c-no\">279</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"280\"><span class=\"c-no\">280</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">self</span>.is_read_only</span></div>\n<div class=\"c-line\" data-line=\"281\"><span class=\"c-no\">281</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"282\"><span class=\"c-no\">282</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> match_rule(</span></div>\n<div class=\"c-line\" data-line=\"283\"><span class=\"c-no\">283</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"284\"><span class=\"c-no\">284</span><span class=\"c-src\">        rule_content: str | <span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"285\"><span class=\"c-no\">285</span><span class=\"c-src\">        tool_input: dict[str, Any],</span></div>\n<div class=\"c-line\" data-line=\"286\"><span class=\"c-no\">286</span><span class=\"c-src\">    ) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"287\"><span class=\"c-no\">287</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Check <span class=\"c-kw\">if</span> a permission rule matches the tool input.</span></div>\n<div class=\"c-line\" data-line=\"288\"><span class=\"c-no\">288</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"289\"><span class=\"c-no\">289</span><span class=\"c-src\">        .. note:: This <span class=\"c-kw\">is</span> an optional method. A rule <span class=\"c-kw\">with</span> no content (``<span class=\"c-kw\">None</span>``)</span></div>\n<div class=\"c-line\" data-line=\"290\"><span class=\"c-no\">290</span><span class=\"c-src\">        <span class=\"c-kw\">is</span> a tool-name-level rule that matches every invocation; a rule</span></div>\n<div class=\"c-line\" data-line=\"291\"><span class=\"c-no\">291</span><span class=\"c-src\">        <span class=\"c-kw\">with</span> content requires the tool to override this method <span class=\"c-kw\">with</span> its</span></div>\n<div class=\"c-line\" data-line=\"292\"><span class=\"c-no\">292</span><span class=\"c-src\">        own matching logic, otherwise it returns ``<span class=\"c-kw\">False</span>``.</span></div>\n<div class=\"c-line\" data-line=\"293\"><span class=\"c-no\">293</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"294\"><span class=\"c-no\">294</span><span class=\"c-src\">        This means:</span></div>\n<div class=\"c-line\" data-line=\"295\"><span class=\"c-no\">295</span><span class=\"c-src\">        - ``_FunctionTool`` <span class=\"c-kw\">and</span> ``MCPTool`` (which do <span class=\"c-kw\">not</span> override this)</span></div>\n<div class=\"c-line\" data-line=\"296\"><span class=\"c-no\">296</span><span class=\"c-src\">          can still be controlled at the tool-name level via rules like</span></div>\n<div class=\"c-line\" data-line=\"297\"><span class=\"c-no\">297</span><span class=\"c-src\">          ``{<span class=\"c-str\">&quot;tool_name&quot;</span>: <span class=\"c-str\">&quot;my_tool&quot;</span>, <span class=\"c-str\">&quot;rule_content&quot;</span>: <span class=\"c-kw\">None</span>}``.</span></div>\n<div class=\"c-line\" data-line=\"298\"><span class=\"c-no\">298</span><span class=\"c-src\">        - Specific tools (Bash, Read, Write, Edit, Glob, Grep) override</span></div>\n<div class=\"c-line\" data-line=\"299\"><span class=\"c-no\">299</span><span class=\"c-src\">          this method to support fine-grained pattern matching.</span></div>\n<div class=\"c-line\" data-line=\"300\"><span class=\"c-no\">300</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"301\"><span class=\"c-no\">301</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"302\"><span class=\"c-no\">302</span><span class=\"c-src\">            rule_content (`str | <span class=\"c-kw\">None</span>`):</span></div>\n<div class=\"c-line\" data-line=\"303\"><span class=\"c-no\">303</span><span class=\"c-src\">                The rule pattern to match. ``<span class=\"c-kw\">None</span>`` means &quot;match all</span></div>\n<div class=\"c-line\" data-line=\"304\"><span class=\"c-no\">304</span><span class=\"c-src\">                invocations of this tool&quot; (tool-name-level rule).</span></div>\n<div class=\"c-line\" data-line=\"305\"><span class=\"c-no\">305</span><span class=\"c-src\">            tool_input (`dict[str, Any]`):</span></div>\n<div class=\"c-line\" data-line=\"306\"><span class=\"c-no\">306</span><span class=\"c-src\">                The tool input data</span></div>\n<div class=\"c-line\" data-line=\"307\"><span class=\"c-no\">307</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"308\"><span class=\"c-no\">308</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"309\"><span class=\"c-no\">309</span><span class=\"c-src\">            `bool`:</span></div>\n<div class=\"c-line\" data-line=\"310\"><span class=\"c-no\">310</span><span class=\"c-src\">                <span class=\"c-kw\">True</span> <span class=\"c-kw\">if</span> the rule matches, <span class=\"c-kw\">False</span> otherwise</span></div>\n<div class=\"c-line\" data-line=\"311\"><span class=\"c-no\">311</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"312\"><span class=\"c-no\">312</span><span class=\"c-src\">        <span class=\"c-com\"># None rule_content = tool-name-level rule, matches everything</span></span></div>\n<div class=\"c-line\" data-line=\"313\"><span class=\"c-no\">313</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> rule_content <span class=\"c-kw\">is</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"314\"><span class=\"c-no\">314</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"315\"><span class=\"c-no\">315</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> generate_suggestions(</span></div>\n<div class=\"c-line\" data-line=\"316\"><span class=\"c-no\">316</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"317\"><span class=\"c-no\">317</span><span class=\"c-src\">        tool_input: dict[str, Any],</span></div>\n<div class=\"c-line\" data-line=\"318\"><span class=\"c-no\">318</span><span class=\"c-src\">    ) -&gt; List[PermissionRule]:</span></div>\n<div class=\"c-line\" data-line=\"319\"><span class=\"c-no\">319</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Generate suggested permission rules <span class=\"c-kw\">for</span> the tool input.</span></div>\n<div class=\"c-line\" data-line=\"320\"><span class=\"c-no\">320</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"321\"><span class=\"c-no\">321</span><span class=\"c-src\">        .. note:: Suggest a single tool-name-level rule (``rule_content=<span class=\"c-kw\">None</span>``)</span></div>\n<div class=\"c-line\" data-line=\"322\"><span class=\"c-no\">322</span><span class=\"c-src\">        that allows all invocations of this tool. Tools can override this to</span></div>\n<div class=\"c-line\" data-line=\"323\"><span class=\"c-no\">323</span><span class=\"c-src\">        provide finer-grained suggestions.</span></div>\n<div class=\"c-line\" data-line=\"324\"><span class=\"c-no\">324</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"325\"><span class=\"c-no\">325</span><span class=\"c-src\">        For example:</span></div>\n<div class=\"c-line\" data-line=\"326\"><span class=\"c-no\">326</span><span class=\"c-src\">        - File tools (Read/Write/Edit): suggest a glob pattern covering the</span></div>\n<div class=\"c-line\" data-line=\"327\"><span class=\"c-no\">327</span><span class=\"c-src\">          parent directory (e.g., <span class=\"c-str\">&quot;src/main.py&quot;</span> -&gt; <span class=\"c-str\">&quot;src/**&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"328\"><span class=\"c-no\">328</span><span class=\"c-src\">        - Bash: suggest command prefix patterns (e.g., <span class=\"c-str\">&quot;git commit -m &#x27;xxx&#x27;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"329\"><span class=\"c-no\">329</span><span class=\"c-src\">          -&gt; <span class=\"c-str\">&quot;git commit:*&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"330\"><span class=\"c-no\">330</span><span class=\"c-src\">        - Grep/Glob: suggest patterns based on search paths</span></div>\n<div class=\"c-line\" data-line=\"331\"><span class=\"c-no\">331</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"332\"><span class=\"c-no\">332</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"333\"><span class=\"c-no\">333</span><span class=\"c-src\">            tool_input (`dict[str, Any]`):</span></div>\n<div class=\"c-line\" data-line=\"334\"><span class=\"c-no\">334</span><span class=\"c-src\">                The tool input data</span></div>\n<div class=\"c-line\" data-line=\"335\"><span class=\"c-no\">335</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"336\"><span class=\"c-no\">336</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"337\"><span class=\"c-no\">337</span><span class=\"c-src\">            `List[PermissionRule]`:</span></div>\n<div class=\"c-line\" data-line=\"338\"><span class=\"c-no\">338</span><span class=\"c-src\">                List of suggested permission rules (usually 1, max 5 <span class=\"c-kw\">for</span></span></div>\n<div class=\"c-line\" data-line=\"339\"><span class=\"c-no\">339</span><span class=\"c-src\">                compound operations)</span></div>\n<div class=\"c-line\" data-line=\"340\"><span class=\"c-no\">340</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"341\"><span class=\"c-no\">341</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> [</span></div>\n<div class=\"c-line\" data-line=\"342\"><span class=\"c-no\">342</span><span class=\"c-src\">            PermissionRule(</span></div>\n<div class=\"c-line\" data-line=\"343\"><span class=\"c-no\">343</span><span class=\"c-src\">                tool_name=<span class=\"c-kw\">self</span>.name,</span></div>\n<div class=\"c-line\" data-line=\"344\"><span class=\"c-no\">344</span><span class=\"c-src\">                rule_content=<span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"345\"><span class=\"c-no\">345</span><span class=\"c-src\">                behavior=PermissionBehavior.ALLOW,</span></div>\n<div class=\"c-line\" data-line=\"346\"><span class=\"c-no\">346</span><span class=\"c-src\">                source=<span class=\"c-str\">&quot;suggested&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"347\"><span class=\"c-no\">347</span><span class=\"c-src\">            ),</span></div>\n<div class=\"c-line\" data-line=\"348\"><span class=\"c-no\">348</span><span class=\"c-src\">        ]</span></div>\n<div class=\"c-line\" data-line=\"349\"><span class=\"c-no\">349</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"350\"><span class=\"c-no\">350</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> _path_in_allowed_working_path(</span></div>\n<div class=\"c-line\" data-line=\"351\"><span class=\"c-no\">351</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"352\"><span class=\"c-no\">352</span><span class=\"c-src\">        file_path: str,</span></div>\n<div class=\"c-line\" data-line=\"353\"><span class=\"c-no\">353</span><span class=\"c-src\">        context: PermissionContext,</span></div>\n<div class=\"c-line\" data-line=\"354\"><span class=\"c-no\">354</span><span class=\"c-src\">    ) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"355\"><span class=\"c-no\">355</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Check <span class=\"c-kw\">if</span> a file path <span class=\"c-kw\">is</span> within any allowed working directory.</span></div>\n<div class=\"c-line\" data-line=\"356\"><span class=\"c-no\">356</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"357\"><span class=\"c-no\">357</span><span class=\"c-src\">        A <span class=\"c-str\">&quot;working directory&quot;</span> <span class=\"c-kw\">is</span> the process&<span class=\"c-com\">#x27;s current directory plus any</span></span></div>\n<div class=\"c-line\" data-line=\"358\"><span class=\"c-no\">358</span><span class=\"c-src\">        entries <span class=\"c-kw\">in</span> :attr:`PermissionContext.working_directories`. Paths</span></div>\n<div class=\"c-line\" data-line=\"359\"><span class=\"c-no\">359</span><span class=\"c-src\">        are compared via :func:`os.path.realpath` so that aliases like</span></div>\n<div class=\"c-line\" data-line=\"360\"><span class=\"c-no\">360</span><span class=\"c-src\">        macOS&<span class=\"c-com\">#x27;s ``/tmp`` → ``/private/tmp`` and symlinked working</span></span></div>\n<div class=\"c-line\" data-line=\"361\"><span class=\"c-no\">361</span><span class=\"c-src\">        directories compare equal on both sides.</span></div>\n<div class=\"c-line\" data-line=\"362\"><span class=\"c-no\">362</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"363\"><span class=\"c-no\">363</span><span class=\"c-src\">        Used by tools that conditionally auto-allow file operations <span class=\"c-kw\">in</span></span></div>\n<div class=\"c-line\" data-line=\"364\"><span class=\"c-no\">364</span><span class=\"c-src\">        :attr:`PermissionMode.ACCEPT_EDITS` (e.g. Write, Edit, <span class=\"c-kw\">and</span> the</span></div>\n<div class=\"c-line\" data-line=\"365\"><span class=\"c-no\">365</span><span class=\"c-src\">        filesystem-command branch of Bash).</span></div>\n<div class=\"c-line\" data-line=\"366\"><span class=\"c-no\">366</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"367\"><span class=\"c-no\">367</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"368\"><span class=\"c-no\">368</span><span class=\"c-src\">            file_path (`str`):</span></div>\n<div class=\"c-line\" data-line=\"369\"><span class=\"c-no\">369</span><span class=\"c-src\">                The file path to check.</span></div>\n<div class=\"c-line\" data-line=\"370\"><span class=\"c-no\">370</span><span class=\"c-src\">            context (`PermissionContext`):</span></div>\n<div class=\"c-line\" data-line=\"371\"><span class=\"c-no\">371</span><span class=\"c-src\">                The permission context containing the working directories.</span></div>\n<div class=\"c-line\" data-line=\"372\"><span class=\"c-no\">372</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"373\"><span class=\"c-no\">373</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"374\"><span class=\"c-no\">374</span><span class=\"c-src\">            `bool`:</span></div>\n<div class=\"c-line\" data-line=\"375\"><span class=\"c-no\">375</span><span class=\"c-src\">                <span class=\"c-kw\">True</span> <span class=\"c-kw\">if</span> ``file_path`` <span class=\"c-kw\">is</span> within any allowed working</span></div>\n<div class=\"c-line\" data-line=\"376\"><span class=\"c-no\">376</span><span class=\"c-src\">                directory.</span></div>\n<div class=\"c-line\" data-line=\"377\"><span class=\"c-no\">377</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"378\"><span class=\"c-no\">378</span><span class=\"c-src\">        current_dir = os.getcwd()</span></div>\n<div class=\"c-line\" data-line=\"379\"><span class=\"c-no\">379</span><span class=\"c-src\">        additional_dirs = list(context.working_directories.keys())</span></div>\n<div class=\"c-line\" data-line=\"380\"><span class=\"c-no\">380</span><span class=\"c-src\">        all_working_dirs = [current_dir] + additional_dirs</span></div>\n<div class=\"c-line\" data-line=\"381\"><span class=\"c-no\">381</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"382\"><span class=\"c-no\">382</span><span class=\"c-src\">        abs_file_path = os.path.realpath(os.path.expanduser(file_path))</span></div>\n<div class=\"c-line\" data-line=\"383\"><span class=\"c-no\">383</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"384\"><span class=\"c-no\">384</span><span class=\"c-src\">        <span class=\"c-kw\">for</span> working_dir <span class=\"c-kw\">in</span> all_working_dirs:</span></div>\n<div class=\"c-line\" data-line=\"385\"><span class=\"c-no\">385</span><span class=\"c-src\">            abs_working_dir = os.path.realpath(</span></div>\n<div class=\"c-line\" data-line=\"386\"><span class=\"c-no\">386</span><span class=\"c-src\">                os.path.expanduser(working_dir),</span></div>\n<div class=\"c-line\" data-line=\"387\"><span class=\"c-no\">387</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"388\"><span class=\"c-no\">388</span><span class=\"c-src\">            <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"389\"><span class=\"c-no\">389</span><span class=\"c-src\">                os.path.relpath(abs_file_path, abs_working_dir)</span></div>\n<div class=\"c-line\" data-line=\"390\"><span class=\"c-no\">390</span><span class=\"c-src\">                <span class=\"c-kw\">if</span> (</span></div>\n<div class=\"c-line\" data-line=\"391\"><span class=\"c-no\">391</span><span class=\"c-src\">                    abs_file_path.startswith(abs_working_dir + os.sep)</span></div>\n<div class=\"c-line\" data-line=\"392\"><span class=\"c-no\">392</span><span class=\"c-src\">                    <span class=\"c-kw\">or</span> abs_file_path == abs_working_dir</span></div>\n<div class=\"c-line\" data-line=\"393\"><span class=\"c-no\">393</span><span class=\"c-src\">                ):</span></div>\n<div class=\"c-line\" data-line=\"394\"><span class=\"c-no\">394</span><span class=\"c-src\">                    <span class=\"c-kw\">return</span> <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"395\"><span class=\"c-no\">395</span><span class=\"c-src\">            <span class=\"c-kw\">except</span> ValueError:</span></div>\n<div class=\"c-line\" data-line=\"396\"><span class=\"c-no\">396</span><span class=\"c-src\">                <span class=\"c-com\"># On Windows, relpath raises ValueError if paths are on</span></span></div>\n<div class=\"c-line\" data-line=\"397\"><span class=\"c-no\">397</span><span class=\"c-src\">                <span class=\"c-com\"># different drives.</span></span></div>\n<div class=\"c-line\" data-line=\"398\"><span class=\"c-no\">398</span><span class=\"c-src\">                <span class=\"c-kw\">continue</span></span></div>\n<div class=\"c-line\" data-line=\"399\"><span class=\"c-no\">399</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"400\"><span class=\"c-no\">400</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"401\"><span class=\"c-no\">401</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"402\"><span class=\"c-no\">402</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> _is_dangerous_path(<span class=\"c-kw\">self</span>, file_path: str) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"403\"><span class=\"c-no\">403</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Check <span class=\"c-kw\">if</span> a file path <span class=\"c-kw\">is</span> dangerous (sensitive file <span class=\"c-kw\">or</span> directory).</span></div>\n<div class=\"c-line\" data-line=\"404\"><span class=\"c-no\">404</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"405\"><span class=\"c-no\">405</span><span class=\"c-src\">        A path <span class=\"c-kw\">is</span> considered dangerous <span class=\"c-kw\">if</span>:</span></div>\n<div class=\"c-line\" data-line=\"406\"><span class=\"c-no\">406</span><span class=\"c-src\">        1. The filename matches a dangerous file (e.g., .bashrc, .gitconfig)</span></div>\n<div class=\"c-line\" data-line=\"407\"><span class=\"c-no\">407</span><span class=\"c-src\">        2. Any path segment matches a dangerous directory (e.g., .git, .ssh)</span></div>\n<div class=\"c-line\" data-line=\"408\"><span class=\"c-no\">408</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"409\"><span class=\"c-no\">409</span><span class=\"c-src\">        Case-insensitive matching <span class=\"c-kw\">is</span> used to prevent bypasses on</span></div>\n<div class=\"c-line\" data-line=\"410\"><span class=\"c-no\">410</span><span class=\"c-src\">        case-insensitive filesystems (macOS, Windows).</span></div>\n<div class=\"c-line\" data-line=\"411\"><span class=\"c-no\">411</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"412\"><span class=\"c-no\">412</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"413\"><span class=\"c-no\">413</span><span class=\"c-src\">            file_path (`str`):</span></div>\n<div class=\"c-line\" data-line=\"414\"><span class=\"c-no\">414</span><span class=\"c-src\">                The file path to check</span></div>\n<div class=\"c-line\" data-line=\"415\"><span class=\"c-no\">415</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"416\"><span class=\"c-no\">416</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"417\"><span class=\"c-no\">417</span><span class=\"c-src\">            `bool`:</span></div>\n<div class=\"c-line\" data-line=\"418\"><span class=\"c-no\">418</span><span class=\"c-src\">                <span class=\"c-kw\">True</span> <span class=\"c-kw\">if</span> the path <span class=\"c-kw\">is</span> dangerous <span class=\"c-kw\">and</span> should require explicit</span></div>\n<div class=\"c-line\" data-line=\"419\"><span class=\"c-no\">419</span><span class=\"c-src\">                permission</span></div>\n<div class=\"c-line\" data-line=\"420\"><span class=\"c-no\">420</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"421\"><span class=\"c-no\">421</span><span class=\"c-src\">        Example:</span></div>\n<div class=\"c-line\" data-line=\"422\"><span class=\"c-no\">422</span><span class=\"c-src\">            &gt;&gt;&gt; <span class=\"c-kw\">self</span>._is_dangerous_path(<span class=\"c-str\">&quot;/home/user/.bashrc&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"423\"><span class=\"c-no\">423</span><span class=\"c-src\">            <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"424\"><span class=\"c-no\">424</span><span class=\"c-src\">            &gt;&gt;&gt; <span class=\"c-kw\">self</span>._is_dangerous_path(<span class=\"c-str\">&quot;/home/user/.git/config&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"425\"><span class=\"c-no\">425</span><span class=\"c-src\">            <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"426\"><span class=\"c-no\">426</span><span class=\"c-src\">            &gt;&gt;&gt; <span class=\"c-kw\">self</span>._is_dangerous_path(<span class=\"c-str\">&quot;/home/user/project/main.py&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"427\"><span class=\"c-no\">427</span><span class=\"c-src\">            <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"428\"><span class=\"c-no\">428</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"429\"><span class=\"c-no\">429</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"430\"><span class=\"c-no\">430</span><span class=\"c-src\">        <span class=\"c-com\"># Normalize path</span></span></div>\n<div class=\"c-line\" data-line=\"431\"><span class=\"c-no\">431</span><span class=\"c-src\">        abs_path = os.path.abspath(os.path.expanduser(file_path))</span></div>\n<div class=\"c-line\" data-line=\"432\"><span class=\"c-no\">432</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"433\"><span class=\"c-no\">433</span><span class=\"c-src\">        <span class=\"c-com\"># Split path into segments</span></span></div>\n<div class=\"c-line\" data-line=\"434\"><span class=\"c-no\">434</span><span class=\"c-src\">        path_parts = Path(abs_path).parts</span></div>\n<div class=\"c-line\" data-line=\"435\"><span class=\"c-no\">435</span><span class=\"c-src\">        path_parts_lower = [p.lower() <span class=\"c-kw\">for</span> p <span class=\"c-kw\">in</span> path_parts]</span></div>\n<div class=\"c-line\" data-line=\"436\"><span class=\"c-no\">436</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"437\"><span class=\"c-no\">437</span><span class=\"c-src\">        <span class=\"c-com\"># Check if filename matches dangerous files (case-insensitive)</span></span></div>\n<div class=\"c-line\" data-line=\"438\"><span class=\"c-no\">438</span><span class=\"c-src\">        filename = os.path.basename(abs_path)</span></div>\n<div class=\"c-line\" data-line=\"439\"><span class=\"c-no\">439</span><span class=\"c-src\">        filename_lower = filename.lower()</span></div>\n<div class=\"c-line\" data-line=\"440\"><span class=\"c-no\">440</span><span class=\"c-src\">        <span class=\"c-kw\">for</span> dangerous_file <span class=\"c-kw\">in</span> <span class=\"c-kw\">self</span>.dangerous_files:</span></div>\n<div class=\"c-line\" data-line=\"441\"><span class=\"c-no\">441</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> filename_lower == dangerous_file.lower():</span></div>\n<div class=\"c-line\" data-line=\"442\"><span class=\"c-no\">442</span><span class=\"c-src\">                <span class=\"c-kw\">return</span> <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"443\"><span class=\"c-no\">443</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"444\"><span class=\"c-no\">444</span><span class=\"c-src\">        <span class=\"c-com\"># Check if any path segment matches dangerous directories</span></span></div>\n<div class=\"c-line\" data-line=\"445\"><span class=\"c-no\">445</span><span class=\"c-src\">        <span class=\"c-com\"># (case-insensitive)</span></span></div>\n<div class=\"c-line\" data-line=\"446\"><span class=\"c-no\">446</span><span class=\"c-src\">        <span class=\"c-kw\">for</span> dangerous_dir <span class=\"c-kw\">in</span> <span class=\"c-kw\">self</span>.dangerous_directories:</span></div>\n<div class=\"c-line\" data-line=\"447\"><span class=\"c-no\">447</span><span class=\"c-src\">            dangerous_dir_lower = dangerous_dir.lower()</span></div>\n<div class=\"c-line\" data-line=\"448\"><span class=\"c-no\">448</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> dangerous_dir_lower <span class=\"c-kw\">in</span> path_parts_lower:</span></div>\n<div class=\"c-line\" data-line=\"449\"><span class=\"c-no\">449</span><span class=\"c-src\">                <span class=\"c-kw\">return</span> <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"450\"><span class=\"c-no\">450</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"451\"><span class=\"c-no\">451</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"452\"><span class=\"c-no\">452</span><span class=\"c-src\">&nbsp;</span></div>\n</div>", "lines": 452, "explanation": "_base.py 来自 agentscope/QwenPaw 框架源码。结合左侧源码与右侧知识点理解此处设计意图；点「反向链接」可回到引用它的教程章节。", "knowledge_points": [], "related_docs": ["agentscope-改造清单"]};
